import{_ as t,o as a,c as i,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const h=JSON.parse('{"title":"第 5 章 加载一个真正用得上的 Skill","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 5 章 加载一个真正用得上的 Skill.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 5 章 加载一个真正用得上的 Skill.md"}'),o={name:"bluebook/第一篇 使用手册：先把我用起来/第 5 章 加载一个真正用得上的 Skill.md"};function s(d,l,r,n,k,p){return a(),i("div",null,[...l[0]||(l[0]=[e(`<h1 id="第-5-章-加载一个真正用得上的-skill" tabindex="-1">第 5 章 加载一个真正用得上的 Skill <a class="header-anchor" href="#第-5-章-加载一个真正用得上的-skill" aria-label="Permalink to &quot;第 5 章 加载一个真正用得上的 Skill&quot;">​</a></h1><h2 id="_5-1-什么是-skill" tabindex="-1">5.1 什么是 Skill <a class="header-anchor" href="#_5-1-什么是-skill" aria-label="Permalink to &quot;5.1 什么是 Skill&quot;">​</a></h2><p>Skill 是把&quot;一次成功的做法&quot;打包成<strong>可随时调用的技能</strong>。它类似电脑里的快捷方式：不用每次重讲方法，喊名字就能用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill = 明确的使用方法 + 执行步骤 + 输入输出约定</span></span></code></pre></div><p>我身上就挂着一些 Skill，比如提交代码（commit）、评审 PR（review-pr）、处理 PDF（pdf）等。它们解决的问题是：<strong>同一件事，每次都按最佳实践做，而不是每次从头想。</strong></p><h2 id="_5-2-我的-skill-长什么样" tabindex="-1">5.2 我的 Skill 长什么样 <a class="header-anchor" href="#_5-2-我的-skill-长什么样" aria-label="Permalink to &quot;5.2 我的 Skill 长什么样&quot;">​</a></h2><p>一个 Skill 通常包含：</p><table tabindex="0"><thead><tr><th>部分</th><th>内容</th><th>示例</th></tr></thead><tbody><tr><td>名称</td><td>调用名</td><td><code>commit</code>、<code>review-pr</code></td></tr><tr><td>说明</td><td>什么时候用</td><td>&quot;提交代码前，先看 diff 再提交&quot;</td></tr><tr><td>步骤</td><td>执行流程</td><td>查状态 → 看改动 → 写 commit message</td></tr><tr><td>约定</td><td>约束与边界</td><td>不强制 push、不 --no-verify</td></tr></tbody></table><h2 id="_5-3-怎么加载一个-skill" tabindex="-1">5.3 怎么加载一个 Skill <a class="header-anchor" href="#_5-3-怎么加载一个-skill" aria-label="Permalink to &quot;5.3 怎么加载一个 Skill&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：用 commit 技能，帮我提交这次的改动</span></span>
<span class="line"><span>我：（加载 commit Skill）先 git status 看改动 → 逐个文件过 diff → 写规范的提交信息 → 提交</span></span></code></pre></div><p>两步走：</p><ol><li>告诉我<strong>技能名 + 目标</strong>；</li><li>我按技能的标准流程执行。</li></ol><p>如果你想不起技能名，直接描述目标（&quot;帮我提交代码&quot;），我自己会匹配。</p><h2 id="_5-4-什么时候别用-skill" tabindex="-1">5.4 什么时候别用 Skill <a class="header-anchor" href="#_5-4-什么时候别用-skill" aria-label="Permalink to &quot;5.4 什么时候别用 Skill&quot;">​</a></h2><ul><li>一次性、不重复的任务：直接对话即可；</li><li>需要即兴发挥的任务：Skill 反而束缚；</li><li>超出技能边界的任务：Skill 会明确告诉我做不了。</li></ul><p><strong>Skill 是锦上添花，不是银弹。</strong> 判断标准很简单：这件事你（或团队）会反复做吗？会 → 值得做成 Skill。</p><h2 id="_5-5-练习" tabindex="-1">5.5 练习 <a class="header-anchor" href="#_5-5-练习" aria-label="Permalink to &quot;5.5 练习&quot;">​</a></h2><ol><li>让我列出当前可用的 Skill。</li><li>挑一个与你的工作相关的 Skill，实际调用一次。</li><li>记录：这个 Skill 解决了我什么问题？省了多少时间？</li></ol><blockquote><p>小结：Skill 的本质是<strong>经验的封装</strong>。用别人的 Skill 是抄作业，做自己的 Skill 是写教材——后者在第三篇（第 17 章）详讲。</p></blockquote>`,19)])])}const _=t(o,[["render",s]]);export{h as __pageData,_ as default};
